import sys
import numpy as np
import pyaudio
import wave
from pydub import AudioSegment
from PyQt6.QtWidgets import (QApplication, QMainWindow, QWidget, QVBoxLayout, QHBoxLayout,
                             QPushButton, QLabel, QFileDialog, QComboBox, QFrame)
from PyQt6.QtGui import QIcon, QFont
from PyQt6.QtCore import QTimer, Qt
import pyqtgraph as pg
from pyqtgraph import PlotWidget

class EchoLangVisualizer(QMainWindow):
    def __init__(self):
        super().__init__()

        self.setWindowTitle("EchoLang Audio Visualizer")
        self.setGeometry(100, 100, 1200, 800)

        self.audio_file = None
        self.file_name = ""
        self.is_playing = False
        self.stream = None
        self.wf = None
        self.p = pyaudio.PyAudio()

        self.init_ui()

        self.timer = QTimer()
        self.timer.setInterval(30)
        self.timer.timeout.connect(self.update_visualizer)

    def init_ui(self):
        self.setStyleSheet("""
            QMainWindow {
                background-color: #0f172a;
            }
            QLabel {
                color: #e2e8f0;
                font-size: 16px;
            }
            QPushButton {
                background-color: #4f46e5;
                color: white;
                font-weight: bold;
                border-radius: 8px;
                padding: 12px;
                font-size: 14px;
            }
            QPushButton:hover {
                background-color: #4338ca;
            }
            QPushButton:disabled {
                background-color: #4b5563;
            }
            QComboBox {
                background-color: #334155;
                color: white;
                font-weight: bold;
                border-radius: 8px;
                padding: 12px;
                font-size: 14px;
            }
            QFrame {
                background-color: #1e293b;
                border-radius: 16px;
                border: 1px solid #4f46e5;
            }
        """)

        central_widget = QWidget()
        self.setCentralWidget(central_widget)
        main_layout = QVBoxLayout(central_widget)

        # Header
        header_layout = QVBoxLayout()
        header_layout.setContentsMargins(0, 0, 0, 20)
        title_label = QLabel("EchoLang Audio Visualizer")
        title_label.setFont(QFont("Arial", 32, QFont.Weight.Bold))
        title_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        subtitle_label = QLabel("Upload any song and watch the beats come alive")
        subtitle_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        subtitle_label.setStyleSheet("color: #94a3b8;")
        header_layout.addWidget(title_label)
        header_layout.addWidget(subtitle_label)
        main_layout.addLayout(header_layout)

        # Visualizer Canvas
        canvas_frame = QFrame()
        canvas_layout = QVBoxLayout(canvas_frame)
        self.plot_widget = PlotWidget()
        self.plot_widget.setBackground(None)
        self.plot_widget.getPlotItem().hideAxis('bottom')
        self.plot_widget.getPlotItem().hideAxis('left')
        self.plot_widget.setYRange(0, 255)
        canvas_layout.addWidget(self.plot_widget)
        main_layout.addWidget(canvas_frame, 1)


        # Controls
        controls_frame = QFrame()
        controls_layout = QVBoxLayout(controls_frame)
        controls_grid = QHBoxLayout()

        upload_button = QPushButton("Upload Audio File")
        upload_button.clicked.connect(self.handle_file_upload)
        self.play_pause_button = QPushButton("Play")
        self.play_pause_button.clicked.connect(self.toggle_play)
        self.play_pause_button.setEnabled(False)
        self.visual_mode_combo = QComboBox()
        self.visual_mode_combo.addItems(["Frequency Bars", "Waveform", "Circular Spectrum"])
        self.visual_mode_combo.currentTextChanged.connect(self.clear_visualizer)


        controls_grid.addWidget(upload_button)
        controls_grid.addWidget(self.play_pause_button)
        controls_grid.addWidget(self.visual_mode_combo)
        controls_layout.addLayout(controls_grid)

        self.file_name_label = QLabel("No file selected.")
        self.file_name_label.setStyleSheet("color: #94a3b8; padding-top: 10px;")
        controls_layout.addWidget(self.file_name_label)
        main_layout.addWidget(controls_frame)

    def handle_file_upload(self):
        file_path, _ = QFileDialog.getOpenFileName(self, "Open Audio File", "", "Audio Files (*.wav *.mp3)")
        if file_path:
            if file_path.endswith('.mp3'):
                sound = AudioSegment.from_mp3(file_path)
                file_path = "temp.wav"
                sound.export(file_path, format="wav")

            self.audio_file = file_path
            self.file_name = file_path.split('/')[-1]
            self.file_name_label.setText(f"Now Playing: {self.file_name}")
            self.play_pause_button.setEnabled(True)
            self.is_playing = False
            self.play_pause_button.setText("Play")

    def toggle_play(self):
        if self.is_playing:
            self.is_playing = False
            self.play_pause_button.setText("Play")
            self.timer.stop()
            if self.stream:
                self.stream.stop_stream()
        else:
            if self.audio_file:
                self.is_playing = True
                self.play_pause_button.setText("Pause")
                self.start_audio_stream()
                self.timer.start()

    def start_audio_stream(self):
        if self.stream:
            self.stream.close()
        if self.wf:
            self.wf.close()

        self.wf = wave.open(self.audio_file, 'rb')
        self.stream = self.p.open(format=self.p.get_format_from_width(self.wf.getsampwidth()),
                                  channels=self.wf.getnchannels(),
                                  rate=self.wf.getframerate(),
                                  output=True,
                                  stream_callback=self.audio_callback)
        self.stream.start_stream()

    def audio_callback(self, in_data, frame_count, time_info, status):
        data = self.wf.readframes(frame_count)
        return (data, pyaudio.paContinue)
    
    def clear_visualizer(self):
        self.plot_widget.clear()
        if self.visual_mode_combo.currentText() == "Circular Spectrum":
            self.plot_widget.setAspectLocked(True)
        else:
            self.plot_widget.setAspectLocked(False)


    def update_visualizer(self):
        if self.is_playing and self.stream:
            raw_data = self.wf.readframes(1024)
            if len(raw_data) == 0:
                self.toggle_play()
                return

            data = np.frombuffer(raw_data, dtype=np.int16)
            
            # For simplicity, we'll take the FFT of a chunk of the data
            fft_data = np.abs(np.fft.rfft(data))
            freq = np.fft.rfftfreq(len(data))
            
            # Normalize and scale the FFT data for visualization
            self.fft_data = np.clip(fft_data[:128] / (np.max(fft_data) + 1e-8) * 255, 0, 255)


            self.plot_widget.clear()
            visual_mode = self.visual_mode_combo.currentText()
            if visual_mode == "Frequency Bars":
                self.draw_bars()
            elif visual_mode == "Waveform":
                 self.draw_wave(data)
            elif visual_mode == "Circular Spectrum":
                self.draw_circle()

    def draw_bars(self):
        x = np.arange(len(self.fft_data))
        bar_graph = pg.BarGraphItem(x=x, height=self.fft_data, width=0.8, brush='b')
        self.plot_widget.addItem(bar_graph)
        self.plot_widget.setYRange(0, 255)


    def draw_wave(self, data):
        self.plot_widget.setYRange(-32768, 32767)
        self.plot_widget.plot(data, pen=pg.mkPen(color='b', width=2))
    
    def draw_circle(self):
        self.plot_widget.setYRange(-250, 250)
        self.plot_widget.setXRange(-250, 250)
        
        num_points = len(self.fft_data)
        angles = np.linspace(0, 2 * np.pi, num_points, endpoint=False)
        radius = 100 + self.fft_data * 0.5 
        
        x = radius * np.cos(angles)
        y = radius * np.sin(angles)
        
        self.plot_widget.plot(np.append(x, x[0]), np.append(y, y[0]), pen=pg.mkPen(color=(147, 51, 234), width=2))


    def closeEvent(self, event):
        self.timer.stop()
        if self.stream:
            self.stream.stop_stream()
            self.stream.close()
        if self.wf:
            self.wf.close()
        self.p.terminate()
        event.accept()


if __name__ == '__main__':
    app = QApplication(sys.argv)
    visualizer = EchoLangVisualizer()
    visualizer.show()
    sys.exit(app.exec())
